  "results.compressedNote": "DeepSeek V4 তার কনটেক্সটের বেশিরভাগ সংকুচিত রাখে: CSA লেয়ারে প্রতি 4 টোকেনে একটি এন্ট্রি, HCA লেয়ারে প্রতি 128 টোকেনে একটি। প্রতিটি অনুরোধের KV ক্যাশের {grow} হলো সেই সংকুচিত কনটেক্সট। বাকি {fixed} কনটেক্সটের সাথে বাড়ে না: প্রতিটি লেয়ারের শেষ {w} টোকেন এবং কম্প্রেসরের কাজের অবস্থা, যা vLLM দুটি ব্যাচে একসাথে চলমান থাকতে পারা {tokens} টোকেনের জন্য আলাদা করে রাখে।",
  "results.compressedNote41": "DeepSeek V4.1 তার কনটেক্সটের বেশিরভাগ সংকুচিত রাখে, কয়েকটি সোর্স লেয়ারে, যাদের কপি ওপরের লেয়ারগুলো পড়ে: প্রতি 2 টোকেনে বা প্রতি টোকেনে একটি এন্ট্রি। প্রতিটি অনুরোধের KV ক্যাশের {grow} হলো সেই সংকুচিত কনটেক্সট। বাকি {fixed} কনটেক্সটের সাথে বাড়ে না: প্রতিটি লেয়ারের শেষ {w} টোকেন, যা vLLM দুটি ব্যাচে একসাথে চলমান থাকতে পারা {tokens} টোকেনের জন্য আলাদা করে রাখে, এবং কম্প্রেসরগুলোর কাজের অবস্থা।",
  "results.overheadNote.none": "70 GB-এর কম মেমরির GPU-তে vLLM 0.31 যেভাবে হিসাব করে, প্রতি GPU-তে সেই ওভারহেড: ব্যাচ করা {tokens} টোকেনের ওপর একটি প্রোফাইলিং পাস এবং {seqs}টি সিকোয়েন্সের বাফার। নির্দিষ্ট GPU-এর নিজস্ব ডিফল্ট দেখতে একটি GPU বেছে নিন।",
  "results.overheadNote.multi": "একাধিক GPU-তে এটি একটি নিম্নসীমা: একাধিক GPU-তে ভাগ করা বড় MoE মডেলের প্রকাশিত vLLM লগে, বিশেষত expert parallelism-এ, প্রতি GPU-তে 2 থেকে 10 GiB বেশি দেখা যায়, কমিউনিকেশন ও বিশেষজ্ঞ-রাউটিং বাফারে, যা এই হিসাব এখনও মডেল করে না।",
