  "gpu.speedNote": "দুটি সীমার মধ্যে যেটি ধীর — পিকের {p}%-এ ব্যান্ডউইথ, কারণ প্রতিটি টোকেন সক্রিয় ওজন ও KV ক্যাশ পড়ে, এবং পিকের {c}%-এ dense tensor throughput — তার সাথে প্রতি ধাপের স্থির খরচ, প্রতি লেয়ারে প্রায় {l} ms। একটি NVIDIA GPU-তে এটি vLLM 0.31-এর পরিমাপ ও প্রকাশিত ব্যাচ-1 সংখ্যার প্রায় 10–15%-এর মধ্যে থাকে, MoE মডেলসহ; 4 থেকে 16 সিকোয়েন্সে একটি MoE দেখানোর চেয়ে 25% পর্যন্ত দ্রুত চলে। Strix Halo-তে, vLLM-এর ROCm বিল্ড দিয়ে মাপা, একটি সিকোয়েন্সও মেলে, কিন্তু চারটির বেশি সিকোয়েন্স দেখানোর চেয়ে 2.5× পর্যন্ত ধীরে চলে; অন্যান্য AMD, Apple ও ইউনিফাইড মেমরি ডিভাইসে এটি এখনও একটি ঊর্ধ্বসীমা।",
  "gpu.speedNoteBw": "পিকের {p}%-এ ব্যান্ডউইথ-সীমিত হিসাব, সাথে প্রতি ধাপের স্থির খরচ, প্রতি লেয়ারে প্রায় {l} ms: প্রতিটি টোকেন সক্রিয় ওজন ও KV ক্যাশ পড়ে। এই ডিভাইসের কোনো tensor throughput তালিকাভুক্ত নেই, তাই বড় ব্যাচ কম্পিউট দিয়ে সীমিত হয় না, এবং সংখ্যাটি একটি ঊর্ধ্বসীমা।",
