  "speed.knee": "{b}টি সিকোয়েন্স থেকে (ছায়াযুক্ত অংশ) ব্যান্ডউইথের বদলে tensor throughput গতি ঠিক করে, তাই আরও ব্যবহারকারী যোগ করলে থ্রুপুট আর বাড়ে না।",
  "speed.noKnee": "পুরো পরিসর জুড়ে ব্যান্ডউইথই গতি ঠিক করে: প্রতি ধাপে পড়া KV ক্যাশ ব্যাচের সাথে বাড়ে।",
  "speed.noTflops": "এই ডিভাইসের কোনো tensor throughput তালিকাভুক্ত নেই, তাই কার্ভটি শুধু ব্যান্ডউইথের সীমা দেখায়।",
  "speed.note": "প্রথম টোকেন লেটেন্সি একটি একক অনুরোধের জন্য, কিউ ছাড়া, এবং এতে প্রথম টোকেনের আগে প্রতিটি অনুরোধে vLLM-এর প্রায় 6 ms খরচ ধরা আছে; কার্ভটি প্রতি সিকোয়েন্সে {n} টোকেন ধরে নেয়। ব্যান্ডউইথ নির্মাতার পিকের {bw}% এবং dense tensor throughput {fl}% ধরা হয়েছে, সাথে প্রতিটি ধাপে প্রতি লেয়ারের একটি স্থির খরচ। RTX 4070 Ti-তে vLLM 0.31 দিয়ে এবং প্রকাশিত সংখ্যার সাথে মিলিয়ে ক্যালিব্রেট করা: একক GPU-তে ডিকোড প্রায় 10–15%-এর মধ্যে, লেয়ারপ্রতি দুটি all-reduce সহ মাল্টি-GPU ডিকোড প্রায় 15%-এর মধ্যে। Strix Halo-তে, vLLM-এর ROCm বিল্ড দিয়ে মাপা, একটি সিকোয়েন্স ও দীর্ঘ প্রম্পটও মেলে, অথচ চারটির বেশি সিকোয়েন্স ও ছোট প্রম্পট দেখানোর চেয়ে 3× পর্যন্ত ধীরে চলে। দীর্ঘ প্রম্পটসহ MoE মডেলের প্রথম টোকেন লেটেন্সি, এবং অন্যান্য AMD, Apple ও ইউনিফাইড মেমরি ডিভাইসের প্রতিটি সংখ্যা ঊর্ধ্বসীমাই থাকে।",
  "speed.noteBw": "কার্ভটি প্রতি সিকোয়েন্সে {n} টোকেন ধরে নেয়, আর ব্যান্ডউইথ নির্মাতার পিকের {bw}% এবং প্রতিটি ধাপে প্রতি লেয়ারের একটি স্থির খরচ ধরে। এই ডিভাইসের কোনো tensor throughput তালিকাভুক্ত নেই, তাই সংখ্যাগুলো ঊর্ধ্বসীমা।",
  "gpu.mig": "MIG প্রোফাইল",
  "gpu.noFitSingle": "ধরে না",
  "gpu.tpTitle": "{n}x GPU মানে টেনসর প্যারালেলিজম",
  "gpu.tpHeadsOk": "{n} দিয়ে {h}টি অ্যাটেনশন হেড সমান ভাগ হয় এবং {kv}টি KV হেডের সাথেও মেলে, তাই vLLM --tensor-parallel-size {n} গ্রহণ করে।",
  "gpu.tpNvlink": "কনজিউমার GPU-তে সাধারণত NVLink বা P2P থাকে না, তাই একটি মডেলকে এগুলোতে ভাগ করে চালানো ধীর।",
  "gpu.tpOverhead": "ওভারহেড ভাগ হয় না: প্রতিটি GPU নিজের রানটাইম বাফার, CUDA graphs ও NCCL বাফার রাখে, আর DeepSeek-ধরনের MLA প্রতিটিতে পুরো ক্যাশ রাখে।",
  "gpu.tpLink": "এই সেটআপটি vLLM পৃষ্ঠায় খুলুন",
  "gpu.epTitle": "expert parallelism সহ {n}x GPU",
  "gpu.dpHow": "শুধু টেনসর প্যারালেলিজম এতগুলো অনুরোধ ধরতে পারে না: KV হেড ফুরিয়ে গেলে একটি গ্রুপের প্রতিটি GPU তার অনুরোধগুলোর পুরো ক্যাশ রাখে। তাই {tp}টি GPU-এর {dp}টি রেপ্লিকা প্রত্যেকে {users}টি অনুরোধের মধ্যে প্রায় {u}টি সার্ভ করে (vLLM-এর --data-parallel-size {dp}, অথবা {dp}টি আলাদা সার্ভার)।",
  "gpu.epHow": "অ্যাটেনশন ডেটা-প্যারালেল চলে, {dp}টি গ্রুপের প্রতিটিতে {users}টি অনুরোধের প্রায় {u}টি, আর {e}টি রাউটেড বিশেষজ্ঞ সব {n}টি GPU-তে ছড়িয়ে থাকে (--data-parallel-size {dp} --enable-expert-parallel); vLLM-এর DeepSeek রেসিপিগুলো এই লেআউটই ব্যবহার করে।",
  "gpu.layoutNone": "এই GPU যতগুলোই হোক, এটি সার্ভ করা যায় না: একটি অনুরোধের ক্যাশ, যা কোনো লেআউট আর ভাগ করে না, ওজনের নিজ অংশসহ একটি GPU-তে ধরে না। কনটেক্সট ছোট করুন, FP8 ক্যাশ ব্যবহার করুন, অথবা আরও বড় একটি GPU বেছে নিন।",
  "gpu.needsNone": "খুব ছোট",
  "gpu.cardNone": "খুব ছোট",
  "gpu.noFitSlice": "এই স্লাইসে ধরে না",
  "gpu.migLayout": "এই MIG স্লাইস এটি ধরতে পারে না, আর vLLM একটি মডেলকে একাধিক স্লাইসে ভাগ করে না। আরও বড় একটি প্রোফাইল বেছে নিন, অথবা পুরো GPU।",
  "gpu.migRequests": "এই MIG স্লাইস মডেলটি ধরে, কিন্তু এই অনুরোধগুলো নয়। কনটেক্সট ছোট করুন, কম ব্যবহারকারীকে সার্ভ করুন, অথবা আরও বড় প্রোফাইল বা পুরো GPU বেছে নিন: vLLM একটি মডেলকে একাধিক স্লাইসে ভাগ করে না।",
