  "gpu.onNone": "একটি অনুরোধও ধরে না: প্রতিটি লেআউটে ওজন ও ওভারহেডের পরে এর ক্যাশের জন্য কোনো জায়গা থাকে না।",
  "gpu.onShortCtx": "{users}টি অনুরোধের জন্য যথেষ্ট নয়: এই কনটেক্সটে {u}টি ধরে, আর সবচেয়ে ছোট কনটেক্সটেও {s}টির বেশি নয়।",
  "gpu.onNoneShort": "একটি অনুরোধও ধরে না: সবচেয়ে ছোট কনটেক্সটেও একটি অনুরোধ যতটা জায়গা সংরক্ষণ করে, ওজন ও ওভারহেডের পরে ততটা বাকি থাকে না।",
  "gpu.ppHow": "{L}টি লেয়ার সর্বোচ্চ {k}টি করে {pp}টি পাইপলাইন স্টেজে ভাগ করা হয়, এবং প্রতিটি স্টেজ শুধু নিজের লেয়ারগুলোর ওজন ও ক্যাশ রাখে। একটি টোকেন পালাক্রমে স্টেজগুলোর মধ্য দিয়ে যায়, তাই এটি একটি দ্রুত উত্তরের চেয়ে একসাথে অনেক অনুরোধের জন্য বেশি উপযোগী।",
  "gpu.dpEach": "{tp}টি GPU-এর {dp}টি রেপ্লিকার প্রতিটি পুরো মডেল রাখে এবং {users}টি অনুরোধের মধ্যে প্রায় {u}টি সার্ভ করে (vLLM-এর --data-parallel-size {dp}, অথবা {dp}টি আলাদা সার্ভার)।",
  "gpu.altTitle": "{n}টি GPU-তে চালানোর সব উপায়",
  "gpu.altHow": "প্রথমে: এই কনটেক্সটে অনুরোধগুলো ধরে এমন দ্রুততম লেআউট (তার 10%-এর মধ্যে থাকা লেআউটগুলোর মধ্যে যেটি সবচেয়ে বেশি ধরে); পাইপলাইন স্টেজ কেবল তখনই, যখন অন্য কোনো লেআউট সেগুলো ধরে না। গতি হলো প্রতিটি অনুরোধ প্রতি সেকেন্ডে কত টোকেন পায় তার আনুমানিক হিসাব।",
