  "gpu.dpOverhead": "ওভারহেড ভাগ হয় না: প্রতিটি GPU নিজের রানটাইম বাফার, CUDA graphs ও কমিউনিকেশন বাফার রাখে, এবং যে অনুরোধগুলো সার্ভ করে সেগুলোর ক্যাশও।",
  "gpu.unifiedSingle": "ইউনিফাইড মেমরির ডিভাইস একটি একক বাক্স — একটি মডেল সার্ভ করতে দ্বিতীয় একটি যোগ করা যায় না। প্রিসিশন কমান, কনটেক্সট ছোট করুন, অথবা বেশি মেমরির একটি ডিভাইস বেছে নিন।",
