  "gpu.w.hint": "শুধু ওজন, প্রতিটি GPU-এর পুরো মেমরির সাথে তুলনা করে",
  "gpu.w.note": "এই মডেল নিজস্ব কোডে চলে, তাই প্রতিটি GPU শুধু এর ওজনের সাথে মিলিয়ে দেখা হয়। এর রানটাইমের অ্যাক্টিভেশন ও কাজের মেমরি গোনা হয় না, এবং একাধিক GPU-তে ভাগ করার হিসাবও করা হয় না: ওজন কোনো GPU-তে ধরলেই মডেলটি সেখানে চলবে, এমন নয়।",
