  "method.summary": "সংখ্যাগুলো কীভাবে হিসাব করা হয়",
  "method.weightsTerm": "ওজন",
  "method.weightsText":
    "= প্যারামিটার × বাইট/প্যারামিটার (FP16/BF16 = 2, FP8/INT8 = 1, INT4 = 0.5)। বিশেষজ্ঞদের মিশ্রণ (MoE) মডেলে সব বিশেষজ্ঞ লোড হয়, তাই মোট প্যারামিটার ধরা হয় — শুধু সক্রিয় অংশ নয়।",
  "method.kvTerm": "KV ক্যাশ",
  "method.kvText": "= 2 × লেয়ার × kv_heads × head_dim × বাইট × কনটেক্সট × সমান্তরাল অনুরোধ। গ্রুপড-কোয়েরি অ্যাটেনশন (kv_heads < attn_heads) এটিকে অনেকখানি কমিয়ে দেয় — এটি প্রতিটি মডেলের কনফিগারেশন থেকে পড়া হয়। Multi-head latent attention (DeepSeek) এর বদলে প্রতি টোকেনে লেয়ার × (kv_lora_rank + qk_rope_head_dim) × বাইট ক্যাশ করে। vLLM যেভাবে সংরক্ষণ করে, সেভাবেই এর আকার হিসাব করা হয়: স্লাইডিং উইন্ডো লেয়ার তার উইন্ডো এবং চলমান প্রতিটি টোকেন (--max-num-batched-tokens-এর দুটি ব্যাচ) রাখে, আর Mamba বা লিনিয়ার-অ্যাটেনশন লেয়ার দুটি স্টেট ব্লক রাখে।",
  "method.overheadTerm": "ওভারহেড",
  "method.overheadText": "হলো ওজন ও ক্যাশের বাইরে vLLM 0.31 প্রতিটি GPU-তে যা রাখে: রানটাইম বাফার (ব্যাচ করা যেতে পারে এমন প্রতিটি সিকোয়েন্সের জন্য প্রতি ভোকাবুলারি এন্ট্রিতে 4 বাইট), এর প্রোফাইলিং পাসের পিক (ব্যাচ করা টোকেনের ওপর ফিড-ফরোয়ার্ড ব্লক ও আউটপুট লেয়ারের মধ্যে যেটি বড়) এবং এর CUDA graphs। টেনসর প্যারালেলিজমে প্রতিটি GPU নিজেরটা রাখে। এগারোটি vLLM স্টার্টআপের সাথে মিলিয়ে দেখা হয়েছে: এটি vLLM-এর নিজস্ব সংখ্যার 0.13 GiB-এর মধ্যে থাকে। প্রতিটি GPU-এর বাজেট ধরা হয় vLLM-এর --gpu-memory-utilization অনুযায়ী, ডিফল্ট 0.92।",
  "method.disclaimer":
    "এই হিসাব পরিকল্পনার জন্য, নিশ্চয়তা নয়। প্রকৃত ব্যবহার সার্ভিং ইঞ্জিন (vLLM, TGI, llama.cpp) এবং তার paged-attention দক্ষতা অনুযায়ী বদলায়।",

