  "footer.privacy": "হিসাব আপনার ব্রাউজারেই চলে — কোনো অ্যাকাউন্ট নেই, কোনো ব্যাকএন্ড নেই। ভিজিট কুকি ছাড়াই, বেনামে গোনা হয়।",
