  "fit.methodNote": "মডেল যা ঘোষণা করে তা থেকে পড়া — আকার, কনটেক্সট, টিউনিং, মোডালিটি। এটি উত্তরের গুণমান, গ্রাউন্ডিং বা হ্যালুসিনেশনের হার দেখতে পায় না, তাই উচ্চ মিলের অর্থ “এর জন্যই তৈরি”, “এতে ভালো” নয়। কেবল আপনার নিজের মূল্যায়নই তা নিশ্চিত করতে পারে।",
