  "train.subtitle":
    "সম্পূর্ণ ফাইন-টিউনিং, LoRA বা QLoRA-তে কতটা GPU মেমরি লাগে, LLMScale তা হিসাব করে: প্রশিক্ষণে KV ক্যাশ লাগে না, কিন্তু যোগ হয় গ্রেডিয়েন্ট, অপ্টিমাইজার স্টেট এবং ব্যাকওয়ার্ড পাসের জন্য রাখা অ্যাক্টিভেশন — এ কারণেই যে মডেল একটি GPU-তে সার্ভ করা যায়, প্রায়ই সেই GPU-তে তার প্রশিক্ষণ দেওয়া যায় না।",
  "train.setup": "প্রশিক্ষণের সেটআপ",
  "train.mode": "পদ্ধতি",
  "train.mode.full": "সম্পূর্ণ",
  "train.modeNote.full": "প্রতিটি প্যারামিটারের প্রশিক্ষণ হয়: ওজন, গ্রেডিয়েন্ট ও Adam স্টেট মিলিয়ে প্রতিটিতে 16 বাইট। অনেক ব্যবধানে সবচেয়ে ভারী বিকল্প।",
  "train.modeNote.lora": "বেস মডেল bf16-এ ফ্রিজ করা থাকে এবং শুধু একটি ছোট অ্যাডাপ্টারের প্রশিক্ষণ হয়, তাই গ্রেডিয়েন্ট ও অপ্টিমাইজার স্টেট প্রায় শূন্যে নামে। অ্যাক্টিভেশন কমে না।",
  "train.modeNote.qlora": "LoRA-এর মতো, তবে ফ্রিজ করা বেস মডেল 4-বিটে রাখা হয় — মেমরিতে থাকা ওজন মোটামুটি এক-চতুর্থাংশ হয়, বেস মডেলের গুণমানে কিছুটা ক্ষতির বিনিময়ে।",
  "train.rank": "LoRA র‍্যাঙ্ক",
