  "train.seg.act": "অ্যাক্টিভেশন",
  "train.seg.overhead": "ওভারহেড",
  "train.noteFull": "অপ্টিমাইজার স্টেটই সবচেয়ে বড়: Adam একটি fp32 মাস্টার কপি ও দুটি মোমেন্ট রাখে, যা bf16 ওজনের নিজের আকারের তিনগুণ।",
  "train.noteAdapter": "বেস মডেল ফ্রিজ করলে গ্রেডিয়েন্ট ও অপ্টিমাইজারের মেমরি প্রায় পুরোটাই চলে যায়, কিন্তু ব্যাকওয়ার্ড পাস তবুও প্রতিটি লেয়ারের মধ্য দিয়ে যায় — তাই অ্যাক্টিভেশনে সম্পূর্ণ ফাইন-টিউনিংয়ের সমান খরচ। হাতে থাকে চেকপয়েন্টিং, ব্যাচ সাইজ ও সিকোয়েন্স দৈর্ঘ্য।",
  "train.gpuFit": "কোন GPU-তে ধরে",
  "train.usableHint": "CUDA কনটেক্সট ও ড্রাইভারের সংরক্ষিত অংশ বাদে প্রতিটি GPU-এর {p}% বরাদ্দ ধরে",
  "train.shardNote": "সার্ভিংয়ের বিপরীতে, এখানে শার্ডিং-ই স্বাভাবিক: FSDP বা DeepSpeed ZeRO-3 প্যারামিটার, গ্রেডিয়েন্ট ও অপ্টিমাইজার স্টেট সব GPU-তে ভাগ করে দেয়, তাই এই মোট প্রায় রৈখিকভাবে ভাগ হয়। অ্যাক্টিভেশন কমে না — সেগুলোর জন্য ব্যাচ সাইজ বা সিকোয়েন্স দৈর্ঘ্য কমান।",
  "train.method": "মিক্সড-প্রিসিশন Adam, 16 বাইট/প্যারামিটার (bf16 ওজন + bf16 গ্রেডিয়েন্ট + fp32 মাস্টার, m ও v)। অ্যাক্টিভেশন Korthikanti et al. 2022 অনুসরণ করে: প্রতি টোকেনে, প্রতি লেয়ারে, প্রতি hidden ইউনিটে ~34 বাইট, flash-attention ধরে নিয়ে, অথবা সম্পূর্ণ পুনর্গণনায় 2 বাইট। বাস্তব রান ফ্রেমওয়ার্ক ও কার্নেলের পছন্দ অনুযায়ী বদলায়; এটিকে পরিকল্পনার সংখ্যা হিসেবে ধরুন।",
