  "compare.tip.params": "মোট প্যারামিটার। বেশি = বেশি সক্ষম/জ্ঞানসমৃদ্ধ, কিন্তু ভারী — বেশি VRAM, ধীর, চালানোর খরচ বেশি।",
  "compare.tip.moe": "MoE সক্রিয় / মোট বিশেষজ্ঞ। সব বিশেষজ্ঞকে VRAM-এ ধরতে হয় (মোট), কিন্তু প্রতি টোকেনে কয়েকটিই চলে (সক্রিয়) — দ্রুত কম্পিউটে বড় ক্ষমতা।",
  "compare.tip.context": "মডেল সর্বোচ্চ যত টোকেনে অ্যাটেনশন দিতে পারে। দীর্ঘ = বড় ডকুমেন্ট / RAG সামলায়, কিন্তু KV ক্যাশ বাড়ে → বেশি VRAM।",
  "compare.tip.license": "ব্যবহারের লাইসেন্স। উদার (Apache/MIT) = কম বিধিনিষেধ; কিছু লাইসেন্স বাণিজ্যিক বা gated ব্যবহার সীমিত করে।",
  "compare.tip.downloads": "30 দিনের ডাউনলোড — গ্রহণযোগ্যতা/জনপ্রিয়তার সংকেত, গুণমানের নয়। বেশি = কমিউনিটিতে বেশি ব্যবহার ও সাপোর্ট।",
  "compare.tip.likes": "Hub-এর লাইক — কমিউনিটির আগ্রহের সংকেত, গুণমানের মাপকাঠি নয়।",
  "compare.tip.updated": "শেষ পরিবর্তনের তারিখ। সাম্প্রতিক = সংশোধন/উন্নতির সম্ভাবনা বেশি, তবে খুব নতুন হলে কম পরীক্ষিত হতে পারে।",
  "compare.tip.base": "যে মডেল থেকে এটি ফাইন-টিউন / কোয়ান্টাইজ করা হয়েছে। বংশধারা দেখায়; সক্ষমতা মূলত সেখান থেকেই আসে।",
  "compare.tip.precision": "ওজনের নেটিভ ফরম্যাট। কম বিট (INT4/FP8) = ছোট ও দ্রুত, তবে BF16/FP16-এর তুলনায় নির্ভুলতা সামান্য কম।",
  "compare.tip.layers": "ট্রান্সফরমার ব্লক (গভীরতা)। বেশি = বেশি ক্ষমতা, কিন্তু বেশি লেটেন্সি এবং প্রতি টোকেনে বেশি KV ক্যাশ।",
  "compare.tip.hidden": "Hidden dimension (প্রস্থ)। বড় = বেশি প্রকাশক্ষমতা, কিন্তু বেশি প্যারামিটার ও মেমরি।",
  "compare.tip.heads": "অ্যাটেনশন / KV হেড। কম KV হেড (GQA) = অনেক ছোট KV ক্যাশ, গুণমানে সামান্যতম ক্ষতি।",
  "compare.tip.headDim": "প্রতিটি অ্যাটেনশন হেডের মাত্রা। head_dim বড় হলে প্রতি টোকেনে KV ক্যাশের আকার বাড়ে।",
  "compare.tip.vocab": "টোকেনাইজারের ভোকাবুলারির আকার। বড় = বহুভাষিক কভারেজ ভালো, কিন্তু এম্বেডিং ম্যাট্রিক্সও বড়।",
  "compare.tip.weights": "মূল প্রিসিশনে ওজনের মেমরি। ছোট = ছোট GPU-তে ধরে; বড় মডেল সাধারণত বেশি সক্ষম।",
  "compare.tip.kvtoken": "প্রতি টোকেনে KV ক্যাশ (FP16)। ছোট = প্রতি GPU-তে বেশি একযোগে ব্যবহারকারী / দীর্ঘ কনটেক্সট (GQA সাহায্য করে)।",
  "compare.tip.vram8k": "8k কনটেক্সট ও 1 জন ব্যবহারকারীতে আনুমানিক মোট VRAM। কম = সার্ভ করা সস্তা / ছোট GPU-তে ধরে।",
  "compare.tip.capGeneric": "✓ = মডেলটি {cap}-এর জন্য টিউন করা/উপযুক্ত; ✗ = এর জন্য বিশেষায়িত নয়।",
  "compare.tip.taskGeneric": "{task}-এর জন্য উপযুক্ততা (0–100)। বেশি = বেশি মানানসই; সারির সেরা মডেলটি হাইলাইট করা থাকে।",
  "anatomy.subtitle":
    "মডেলের একটি ভিজ্যুয়াল এক্স-রে: এর প্যারামিটার কোথায় থাকে, কীভাবে কোয়ান্টাইজ করা হয়েছে, এর অ্যাটেনশনের গঠন এবং KV ক্যাশ কীভাবে বাড়ে — সবই লাইভ Hugging Face ডেটা থেকে।",
