  "decode.subtitle":
    "মডেলের নামের প্রতিটি অংশের মানে কী? একটি মডেলের নাম লিখুন বা বেছে নিন — প্রতিটি টোকেন (আকার, কোয়ান্টাইজেশন, ভ্যারিয়েন্ট…) রঙ দিয়ে চিহ্নিত ও ব্যাখ্যা করা হয়। হাইলাইট করতে হোভার করুন।",
  "decode.input": "মডেলের নাম",
