  "decode.empty": "ডিকোড করতে একটি মডেলের নাম লিখুন।",
  "vllm.subtitle":
    "একটি টিউন করা `vllm serve` কমান্ড তৈরি করুন। একটি মডেল, কী অপ্টিমাইজ করছেন এবং আপনার ওয়ার্কলোড বেছে নিন — LLMScale সেরা পারফরম্যান্স, নির্ভুলতা ও নির্ভরযোগ্যতার জন্য ফ্ল্যাগ সুপারিশ করে, কপি করার মতো কমান্ডসহ।",
  "vllm.pickPriority": "অপ্টিমাইজেশনের লক্ষ্য",
  "vllm.pickTask": "ওয়ার্কলোড",
  "vllm.noMetal": "{gpu} দিয়ে vLLM-এ সার্ভ করা যায় না — Metal ব্যাকএন্ড নেই। H100 80GB-তে বদলানো হয়েছে; ওই GPU-এর মেমরির হিসাব এখনো সাইজিং পৃষ্ঠায় আছে।",
  "vllm.gpuCount": "GPU-এর সংখ্যা",
  "vllm.layout": "লেআউট",
  "vllm.layoutInfo": "এই GPU-গুলোতে vLLM যেসব উপায়ে মডেলটি চালাতে পারে, ক্যালকুলেটর max-model-len-এ একটি অনুরোধের জন্য যেভাবে হিসাব করে সেভাবেই হিসাব করা। প্রথমটি হলো সবচেয়ে দ্রুত লেআউট যাতে মডেলটি ধরে (তার থেকে 10%-এর মধ্যে থাকাগুলোর মধ্যে, যেটিতে সবচেয়ে বেশি অনুরোধ ধরে); থ্রুপুট ও মেমরির জন্য, যেটিতে সবচেয়ে বেশি অনুরোধ ধরে। পাইপলাইন ধাপ কেবল তখনই, যখন অন্য কোনো লেআউটে মডেলটি ধরে না।",
