  "vllm.r.maxlen": "কনটেক্সট উইন্ডো সীমিত করে — মডেলের পূর্ণ সর্বোচ্চ কনটেক্সটের তুলনায় KV ক্যাশের জায়গা খালি করে।",
  "vllm.r.tp": "প্রতিটি লেয়ারকে {n}টি GPU-তে ভাগ করে (টেনসর প্যারালেলিজম)।",
  "vllm.r.tpMoe": "প্রতিটি লেয়ারকে {n}টি GPU-তে ভাগ করে (টেনসর প্যারালেলিজম)। --enable-expert-parallel যোগ করলে রাউটেড বিশেষজ্ঞদের প্রতিটিকে টুকরো না করে পুরোটা রাখা হয়, প্রতিটি GPU-তে তাদের একটি অংশ থাকে (TP+EP, vLLM-এর DeepSeek রেসিপি যা চালায়); এতে প্রায় একই মেমরি লাগে, তাই ক্যালকুলেটর এটিকে আলাদা লেআউট হিসেবে দেখায় না।",
  "vllm.r.pp": "{L}টি লেয়ারকে সর্বোচ্চ {k}টি করে {pp}টি ধাপে ভাগ করে, প্রতিটি ধাপ নিজস্ব GPU-তে (pipeline parallelism)।",
  "vllm.r.dp": "মডেলের {dp}টি কপি চালায়, প্রতিটি কপি অনুরোধের নিজের ভাগ সার্ভ করে (ডেটা প্যারালেলিজম); --max-num-seqs প্রতি কপিতে গোনা হয়।",
  "vllm.r.dpEp": "অ্যাটেনশন {dp}টি ডেটা-প্যারালেল rank-এ চালায়, প্রতিটির নিজস্ব অনুরোধ থাকে; --max-num-seqs প্রতি rank-এ গোনা হয়।",
  "vllm.r.ep": "{e}টি রাউটেড বিশেষজ্ঞের প্রতিটিকে টুকরো না করে পুরোটা সব {n}টি GPU-তে ছড়িয়ে দেয় (expert parallelism)।",
  "vllm.r.kvV4": "DeepSeek V4 তার ক্যাশ DeepSeek-এর fp8_ds_mla সারি হিসেবে রাখে; ওই লেআউটে vLLM 16-বিট ক্যাশ গ্রহণ করে না, আর V4 রেসিপি fp8 সেট করে।",
  "vllm.r.blockV4": "256-টোকেনের ব্লক: V4-এর স্পার্স-অ্যাটেনশন কার্নেল এটাই নেয় এবং এর vLLM রেসিপি এটাই সেট করে; মেমরির হিসাব এগুলো ধরে নিয়েই করা।",
  "vllm.r.gpuutil": "প্রতিটি GPU-এর যে অংশ vLLM ওজন, ওভারহেড ও KV ক্যাশ দিয়ে ভরে; বেশি ক্যাশের জন্য ডিফল্ট 0.92-এর ওপরে সেট করুন।",
  "vllm.r.kvfp8": "FP8 KV ক্যাশ ক্যাশের মেমরি ~অর্ধেক করে — আরও বেশি / দীর্ঘ সিকোয়েন্স ধরে।",
  "vllm.r.maxbatched": "বড় প্রিফিল ব্যাচ থ্রুপুট সর্বোচ্চ করে।",
  "vllm.r.maxbatchedLat": "ছোট প্রিফিল ব্যাচ টোকেনের মধ্যবর্তী লেটেন্সি কমায়।",
  "vllm.r.maxseqs": "থ্রুপুটের জন্য অনেক সমান্তরাল সিকোয়েন্সের অনুমতি দিন।",
  "vllm.r.maxseqsLat": "কম সমান্তরাল সিকোয়েন্স লেটেন্সি কম রাখে।",
  "vllm.r.maxseqsMem": "KV ক্যাশের মেমরি সীমিত রাখতে সমান্তরাল সিকোয়েন্সের সংখ্যা বেঁধে দিন।",
  "vllm.r.tool": "স্বয়ংক্রিয় টুল / ফাংশন কলিং চালু করে।",
  "vllm.r.toolparser": "এই মডেল পরিবারের সাথে মেলে এমন পার্সার ({parser})।",
  "vllm.r.chatTemplate": "vLLM-এর নিজস্ব রিপোজিটরি থেকে একটি চ্যাট টেমপ্লেট (পাথটি তার ভেতরে), যা এই পরিবারের জন্য টুল রেন্ডার করে।",
  "vllm.r.reasoningParser": "চ্যাট টেমপ্লেট দেখায় যে মডেলটি চিন্তা করে: এটি চিন্তাকে উত্তর থেকে আলাদা করে reasoning_content-এ রাখে।",
  "vllm.r.guided": "দ্রুত, নির্ভরযোগ্য JSON / গ্রামার আউটপুটের জন্য xgrammar ব্যাকএন্ড। vLLM 0.31.0 এটি দিয়ে --guided-decoding-backend প্রতিস্থাপন করেছে।",
  "vllm.r.mm": "মাল্টিমোডাল ইনপুটের জন্য প্রতি প্রম্পটে ছবির সংখ্যা সীমিত করুন।",
