  "vllm.w.ctxcap": "অনুরোধ করা কনটেক্সট মডেলের সর্বোচ্চ ({max}) ছাড়িয়ে যায় — vLLM এটি প্রত্যাখ্যান করবে অথবা RoPE স্কেলিং লাগবে।",
  "vllm.w.fp8acc": "দীর্ঘ কনটেক্সটের কাজে FP8 KV ক্যাশ নির্ভুলতা কমাতে পারে — প্রোডাকশনের আগে যাচাই করুন।",
  "vllm.w.kvfull": "সর্বোচ্চ নির্ভুলতার জন্য KV ক্যাশ পূর্ণ প্রিসিশনে (auto) রাখা হয়েছে।",
  "vllm.w.template": "এই পার্সারের সাধারণত মডেল-নির্দিষ্ট --chat-template লাগে (vLLM examples/ দেখুন)।",
  "vllm.w.parserUnknown": "টুল-কল পার্সার শনাক্ত করা যায়নি — আপনার মডেলের সাথে মিলিয়ে --tool-call-parser সেট করুন।",
  "vllm.w.trust": "অনেক মাল্টিমোডাল মডেলের জন্য --trust-remote-code ফ্ল্যাগও লাগে।",
  "vllm.w.quant": "আগে থেকে কোয়ান্টাইজড মডেল ({q}) — vLLM এটি নিজেই শনাক্ত করে; --quantization লাগবে না।",
  "vllm.w.gguf": "vLLM-এ GGUF সাপোর্ট পরীক্ষামূলক — safetensors/মূল ফরম্যাটের রিপোজিটরি ব্যবহারের পরামর্শ দেওয়া হয়।",
  "vllm.w.seqcap": "--max-num-seqs {fit}-এ সীমিত: {ctx} টোকেনে KV ক্যাশ এর বেশি ধরে না। এটি বাড়ালে শুধু অপেক্ষার সারি লম্বা হয়।",
  "vllm.w.fit": "প্রতিটি GPU-তে ~{need} GiB দরকার, পাওয়া যায় ~{have} GiB। এমন {gpus}টি GPU-তে এটি ধরে ({layout}, ক্যালকুলেটর যেভাবে সাজায়); অথবা কোয়ান্টাইজ করুন, কনটেক্সট ছোট করুন, বা FP8 KV ব্যবহার করুন।",
  "vllm.w.fitNone": "প্রতিটি GPU-তে ~{need} GiB দরকার, পাওয়া যায় ~{have} GiB, এবং যত GPU-ই হোক, {ctx} টোকেনে একটি অনুরোধও ধরে না: কনটেক্সট ছোট করুন, কোয়ান্টাইজ করুন, বা FP8 KV ব্যবহার করুন।",
  "vllm.w.sliding": "স্লাইডিং উইন্ডো লেয়ারগুলো তাদের {w}-টোকেনের উইন্ডো এবং প্রক্রিয়াধীন প্রতিটি টোকেন রাখে, অর্থাৎ --max-num-batched-tokens মাপের দুটি ব্যাচ ({t}): প্রতি সিকোয়েন্সে {held} টোকেন। --max-num-batched-tokens ছোট হলে বেশি সিকোয়েন্স ধরে।",
  "plan.subtitle": "লোড বর্ণনা করুন: কতগুলো অনুরোধ আসে, তাদের প্রম্পট ও উত্তর কত দীর্ঘ, এবং কত দ্রুত উত্তর দিতে হবে। LLMScale হিসাব করে কয়টি vLLM রেপ্লিকা লাগবে এবং প্রতিটি কয়টি GPU-তে চলবে।",
