  "config.a.precision.actDynamic": "অ্যাক্টিভেশন চলার সময়ই কোয়ান্টাইজ করা হয়, স্কেল রানটাইমে গণনা করা হয়।",
  "config.a.precision.kvScheme": "এর সাথে {bits}-বিট KV ক্যাশের জন্য ক্যালিব্রেট করা স্কেলও দেওয়া আছে; এগুলো ব্যবহারের জন্য সেট করা ইঞ্জিন ক্যাশকে 16-এর বদলে {bits} বিটে রাখে।",
  "config.a.precision.kvSchemePlain": "এর সাথে কম প্রিসিশনের KV ক্যাশের জন্য ক্যালিব্রেট করা স্কেলও দেওয়া আছে, যা ব্যবহার করতে একটি ইঞ্জিন সেট করা যায়।",
  "config.a.vocab.size": "এর এম্বেডিং টেবিলে **{v}টি সারি** আছে — টোকেনাইজারের ভোকাবুলারি, প্রায়ই একটি গোল সংখ্যা পর্যন্ত প্যাড করা।",
  "config.a.vocab.tied": "ইনপুট এম্বেডিং ও আউটপুট লেয়ার **একটি ম্যাট্রিক্স ভাগ করে নেয়**, এতে {p} প্যারামিটার বাঁচে।",
  "config.a.vocab.untied": "ইনপুট এম্বেডিং ও আউটপুট লেয়ার **আলাদা ম্যাট্রিক্স**, প্রতিটিতে {p} প্যারামিটার।",
  "config.a.vocab.eosMany": "{n}টি ভিন্ন টোকেন একটি উত্তর শেষ করতে পারে।",
  "config.a.vocab.w.matrix": "vocab_size × hidden_size = {v} × {d} = প্রতি ম্যাট্রিক্সে {p} প্যারামিটার",
  "config.a.load.class": "ওজনগুলো **{arch}** থেকে সংরক্ষণ করা হয়েছে।",
  "config.a.load.version": "ফাইলটি Transformers {v} দিয়ে লেখা।",
  "config.a.load.native": "এতে **কোনো কাস্টম কোডের উল্লেখ নেই**, তাই এটি Transformers-এ অন্তর্নির্মিত একটি আর্কিটেকচারের ওপর নির্ভর করে — সাম্প্রতিক সংস্করণ লাগতে পারে।",
  "config.a.load.remote": "এর সাথে **নিজস্ব মডেলিং কোড** আছে (auto_map)। Transformers এটি কেবল trust_remote_code=True দিলে চালায় — আগে কোডটি পড়ে নিন। আপনার Transformers সংস্করণে এই পরিবার অন্তর্নির্মিত থাকলে এটি ছাড়াই লোড হয়।",
  "config.a.training.some": "**{n}টি ফিল্ড** কেবল ট্রেনিং নিয়ন্ত্রণ করত, সার্ভিংয়ে কিছুই বদলায় না: {list}।",
  "config.a.training.none": "এর কোনো ফিল্ডই শুধু ট্রেনিংয়ের জন্য নয়।",
