  "gpucmp.row.launch": "লঞ্চ",
  "gpucmp.tip.arch": "আর্কিটেকচার, ডাই ও ম্যানুফ্যাকচারিং নোড। টেনসর কোর কোন নম্বর ফরম্যাট নেটিভভাবে চালায়, তা আর্কিটেকচারই ঠিক করে — FP8 Hopper, Ada ও CDNA 3 থেকে, FP4 Blackwell ও CDNA 4 থেকে।",
  "gpucmp.tip.cores": "ভেন্ডর যেভাবে গোনে, সেভাবে শেডার কোর। ভেন্ডরভেদে গণনার নিয়ম আলাদা, তাই এটি একই ভেন্ডর ও একই প্রজন্মের GPU-র মধ্যে তুলনা করে, ভিন্ন ভেন্ডর বা প্রজন্মের মধ্যে নয়।",
  "gpucmp.tip.memType": "মেমরি প্রযুক্তি ও তার ইন্টারফেসের প্রস্থ। ব্যান্ডউইথ হলো এই দুটি আর মেমরি ক্লকের গুণফল: HBM চওড়া ও ধীর, GDDR সরু ও দ্রুত, LPDDR CPU-র সাথে শেয়ার করা।",
  "gpucmp.tip.power": "ভেন্ডরের দেওয়া সর্বোচ্চ বোর্ড, মডিউল বা প্যাকেজ পাওয়ার। সুপারচিপ বা সিস্টেম-অন-চিপের সংখ্যায় তার CPU-ও ধরা থাকে, আর Apple শুধু দেয়ালের সকেটে মাপা পুরো Mac-এর সর্বোচ্চ মান প্রকাশ করে, তাই এগুলো একটি graphics card-এর সাথে সরাসরি তুলনীয় নয়।",
  "gpucmp.tip.host": "ডিভাইসটি কীভাবে তৈরি ও কীভাবে যুক্ত হয়: একটি PCIe card, বেসবোর্ডে বসানো SXM বা OAM মডিউল, অথবা সিস্টেম-অন-চিপ।",
  "gpucmp.tip.link": "এমন দুটি ডিভাইস কীভাবে পরস্পরের সাথে যোগাযোগ করে, ভেন্ডররা যেমন উল্লেখ করে তেমনই দুই দিক মিলিয়ে। টেনসর প্যারালেলিজম প্রতিটি লেয়ারে অ্যাক্টিভেশন আদান-প্রদান করে, তাই মডেল একাধিক GPU-তে ছড়ালে দ্রুত লিংক গুরুত্বপূর্ণ; শুধু PCIe-তে এটি কম ভালোভাবে স্কেল করে। Thunderbolt, USB4 ও Ethernet-এর মান গিগাবিটে দেওয়া।",
  "gpucmp.tip.launch": "ভেন্ডর কখন এটি লঞ্চ করেছে বা সরবরাহ শুরু করেছে।",
  "gpucmp.unified": "{gb} GB ইউনিফাইড",
