  "decode.kind.moe.desc": "বিশেষজ্ঞ × প্রতিটির আকার (যেমন 8x7B)। প্রতি টোকেনে মাত্র কয়েকটি বিশেষজ্ঞ চলে (দ্রুত গণনা), কিন্তু সব বিশেষজ্ঞকেই VRAM-এ এঁটে যেতে হয়।",
  "decode.kind.moeActive.title": "MoE — সক্রিয় প্যারামিটার",
  "decode.kind.moeActive.desc": "প্রতি টোকেনে সক্রিয় প্যারামিটার (যেমন A3B = 3B সক্রিয়)। গণনা ≈ সক্রিয় প্যারামিটার; VRAM ≈ মোট প্যারামিটার।",
  "decode.kind.quantAWQ.title": "কোয়ান্টাইজেশন · AWQ",
  "decode.kind.quantAWQ.desc": "Activation-aware Weight Quantization (~4-বিট)। ~4× ছোট, GPU-তে দ্রুত, নির্ভুলতা সামান্য কমে।",
  "decode.kind.quantGPTQ.title": "কোয়ান্টাইজেশন · GPTQ",
  "decode.kind.quantGPTQ.desc": "GPTQ 4-বিট ওজন কোয়ান্টাইজেশন। ছোট ও GPU-তে দ্রুত; নির্ভুলতা সামান্য কমে।",
  "decode.kind.quantGGUF.title": "ফরম্যাট · GGUF",
  "decode.kind.quantGGUF.desc": "llama.cpp ফরম্যাট — অনেক কোয়ান্ট লেভেলসহ (Q4…Q8) CPU ও GPU-তে চলে। লোকাল / Mac-এর জন্য চমৎকার।",
  "decode.kind.quantFP8.title": "কোয়ান্টাইজেশন · FP8",
