  "decode.kind.quantNVFP4.desc": "4-বিট ফ্লোট (Blackwell-এ NVFP4, MXFP4 যেমন gpt-oss-এ)। ~4× ছোট, INT4-এর চেয়ে ভালো নির্ভুলতা।",
  "decode.kind.quantINT.title": "কোয়ান্টাইজেশন · INT4/INT8",
  "decode.kind.quantINT.desc": "ইন্টিজার কোয়ান্টাইজেশন (4 বা 8-বিট)। ছোট ও দ্রুত; INT4-এ কিছুটা নির্ভুলতা কমে।",
  "decode.kind.quantWA.title": "কোয়ান্টাইজেশন · W/A বিট",
