  "decode.kind.quantBnb.title": "কোয়ান্টাইজেশন · bitsandbytes",
  "decode.kind.quantBnb.desc": "লোড করার সময়ই 4-বিট / 8-বিট (bitsandbytes)। লোড করা সহজ, সীমিত VRAM-এর জন্য ভালো।",
