  "gloss.quantization_config.quant_method.meaning": "স্কিম — যেমন awq, gptq, fp8, mxfp4, bitsandbytes বা compressed-tensors। সার্ভিং ইঞ্জিনগুলো এটি দেখে তাদের কার্নেল বেছে নেয়।",
  "gloss.quantization_config.bits.title": "প্রতি ওজনে বিট",
