  "gloss.quantization_config.group_size.title": "গ্রুপ সাইজ",
  "gloss.quantization_config.group_size.meaning": "পরপর কতগুলো ওজন একটি স্কেল শেয়ার করে। ছোট গ্রুপ বেশি নির্ভুল এবং সামান্য বেশি মেমরি নেয়; -1 মানে প্রতি আউটপুট চ্যানেলে একটি স্কেল, কোনো গ্রুপিং নেই।",
