  "gloss.quantization_config.desc_act.title": "অ্যাক্টিভেশন ক্রম",
  "gloss.quantization_config.desc_act.meaning": "GPTQ অ্যাক্টিভেশনের মাত্রা অনুযায়ী ক্রমে কলামগুলো কোয়ান্টাইজ করেছে কি না — সাধারণত বেশি নির্ভুল, কখনো কখনো ধীর।",
